const products = [
  { id: 1, name: "Klawiatura", price: 249, category: "tech" },
  { id: 2, name: "Lampa", price: 129, category: "home" },
  { id: 3, name: "Mysz", price: 89, category: "tech" },
  { id: 4, name: "Kubek", price: 39, category: "home" },
  { id: 5, name: "Monitor", price: 899, category: "tech" },
  { id: 6, name: "Poduszka", price: 59, category: "home" },
];
const money = new Intl.NumberFormat("pl-PL", { style: "currency", currency: "PLN" });
const cart = new Map();
const productsEl = document.getElementById("products");
const searchEl = document.getElementById("search");
const categoryEl = document.getElementById("category");

function visibleProducts() {
  const query = searchEl.value.trim().toLowerCase();
  return products.filter((product) => {
    const matchesQuery = product.name.toLowerCase().includes(query);
    const matchesCategory = categoryEl.value === "all" || product.category === categoryEl.value;
    return matchesQuery && matchesCategory;
  });
}

function renderProducts() {
  productsEl.innerHTML = visibleProducts().map((product) => `
    <article class="product">
      <h3>${product.name}</h3>
      <p>${money.format(product.price)}</p>
      <button data-add="${product.id}">Dodaj</button>
    </article>`).join("");
}

function renderCart() {
  const entries = [...cart.entries()];
  document.getElementById("cart-count").textContent = [...cart.values()].reduce((a, b) => a + b, 0);
  document.getElementById("cart-list").innerHTML = entries.map(([id, qty]) => {
    const product = products.find((item) => item.id === id);
    return `<li>${product.name} × ${qty}</li>`;
  }).join("");
  const total = entries.reduce((sum, [id, qty]) => {
    const product = products.find((item) => item.id === id);
    return sum + product.price * qty;
  }, 0);
  document.getElementById("cart-total").textContent = money.format(total);
}

productsEl.addEventListener("click", (event) => {
  const button = event.target.closest("[data-add]");
  if (!button) return;
  const id = Number(button.dataset.add);
  cart.set(id, (cart.get(id) ?? 0) + 1);
  renderCart();
});
searchEl.addEventListener("input", renderProducts);
categoryEl.addEventListener("change", renderProducts);
renderProducts();
renderCart();

