const docs = [
  { title: "Promise", text: "Reprezentuje przyszły wynik operacji asynchronicznej." },
  { title: "AbortController", text: "Pozwala anulować fetch i inne operacje." },
  { title: "React useState", text: "Przechowuje stan i planuje render." },
  { title: "DOM", text: "Drzewo dokumentu HTML dostępne z JavaScriptu." },
  { title: "Event loop", text: "Kolejka zadań i mikrozadań w środowisku JS." },
];

function fakeSearch(query, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      resolve(docs.filter((item) => item.title.toLowerCase().includes(query)));
    }, 450);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new DOMException("Anulowano", "AbortError"));
    });
  });
}

const input = document.getElementById("query");
const statusEl = document.getElementById("status");
const resultsEl = document.getElementById("results");
let timeout;
let controller;

async function runSearch(value) {
  if (controller) controller.abort();
  controller = new AbortController();
  if (!value.trim()) { statusEl.textContent = "Wpisz frazę."; resultsEl.innerHTML = ""; return; }
  statusEl.textContent = "Szukam…";
  try {
    const results = await fakeSearch(value.toLowerCase(), controller.signal);
    statusEl.textContent = `${results.length} wyników`;
    resultsEl.innerHTML = results.map((item) => `<li>${item.title}<span>${item.text}</span></li>`).join("");
  } catch (error) {
    if (error.name !== "AbortError") statusEl.textContent = "Błąd wyszukiwania.";
  }
}

input.addEventListener("input", () => {
  clearTimeout(timeout);
  const value = input.value;
  timeout = setTimeout(() => runSearch(value), 300);
});

