const group = document.querySelector(".rating");
const buttons = [...group.querySelectorAll("[role=radio]")];
const text = document.getElementById("rating-text");
let value = 0;

function paint(next) {
  buttons.forEach((button) => {
    const on = Number(button.dataset.value) <= next;
    button.classList.toggle("is-on", on);
    button.setAttribute("aria-checked", String(Number(button.dataset.value) === value));
  });
}
function choose(next) {
  value = next;
  paint(next);
  text.textContent = `Ocena: ${value} / 5`;
}

group.addEventListener("click", (event) => {
  const button = event.target.closest("[role=radio]");
  if (button) choose(Number(button.dataset.value));
});
group.addEventListener("keydown", (event) => {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  event.preventDefault();
  let next = value || 1;
  if (event.key === "ArrowRight") next = Math.min(5, next + 1);
  if (event.key === "ArrowLeft") next = Math.max(1, next - 1);
  if (event.key === "Home") next = 1;
  if (event.key === "End") next = 5;
  buttons[next - 1].focus();
  choose(next);
});
paint(0);

