const data = [
  { label: "pon", value: 12 }, { label: "wt", value: 19 }, { label: "śr", value: 8 },
  { label: "czw", value: 24 }, { label: "pt", value: 30 }, { label: "sob", value: 15 }, { label: "niedz", value: 9 },
];
const canvas = document.getElementById("chart");
const ctx = canvas.getContext("2d");
const max = Math.max(...data.map((item) => item.value));

function draw() {
  const ratio = window.devicePixelRatio || 1;
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  canvas.width = width * ratio;
  canvas.height = height * ratio;
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.clearRect(0, 0, width, height);
  const padding = 24;
  const gap = 8;
  const barWidth = (width - padding * 2 - gap * (data.length - 1)) / data.length;
  const usable = height - 34;
  ctx.font = "10px system-ui";
  data.forEach((item, index) => {
    const barHeight = (item.value / max) * (usable - 16);
    const x = padding + index * (barWidth + gap);
    const y = usable - barHeight;
    ctx.fillStyle = "#f7df1e";
    ctx.fillRect(x, y, barWidth, barHeight);
    ctx.fillStyle = "#1b2a31";
    ctx.textAlign = "center";
    ctx.fillText(String(item.value), x + barWidth / 2, y - 3);
    ctx.fillText(item.label, x + barWidth / 2, height - 10);
  });
}
draw();
window.addEventListener("resize", () => requestAnimationFrame(draw));

