  });
}

function sortProducts(items, currentSort) {
  const factor = currentSort.direction === "desc" ? -1 : 1;
  return [...items].sort((a, b) => {
    if (currentSort.key === "price") return (a.price - b.price) * factor;
    return String(a[currentSort.key]).localeCompare(String(b[currentSort.key]), "pl") * factor;
  });
}

function paginate(items, page, pageSize) {
  const start = (page - 1) * pageSize;
  return items.slice(start, start + pageSize);
}

function selectProducts(items, currentState) {
  return paginate(
    sortProducts(filterProducts(items, currentState), currentState.currentSort),
    currentState.currentPage,
    currentState.pageSize
  );
}

function render() {
  const filtered = filterProducts(products, state);
  const totalPages = Math.max(1, Math.ceil(filtered.length / state.pageSize));
  if (state.currentPage > totalPages) state.currentPage = totalPages;
  const visible = selectProducts(products, state);
  const list = document.getElementById("products");
  list.className = "products " + state.currentView;
  list.innerHTML = visible.length
    ? visible.map((product) => `<article class="product"><strong>${product.name}</strong><span>${money.format(product.price)}</span></article>`).join("")
    : '<p class="empty">Brak wyników dla tych filtrów.</p>';
  document.getElementById("count").textContent = `${filtered.length} produktów`;
  document.getElementById("page").textContent = `${state.currentPage} / ${totalPages}`;
  document.getElementById("prev").disabled = state.currentPage <= 1;
  document.getElementById("next").disabled = state.currentPage >= totalPages;
  document.querySelectorAll("[data-view]").forEach((button) => {
    button.setAttribute("aria-pressed", String(button.dataset.view === state.currentView));
  });
  document.getElementById("state").textContent = JSON.stringify(state, null, 2);
}

function update(patch) {
  state = { ...state, ...patch };
  if ("currentQuery" in patch || "currentCategory" in patch || "currentSort" in patch) {
    state.currentPage = 1;
  }
  render();
}

document.getElementById("query").addEventListener("input", (event) => update({ currentQuery: event.target.value }));
document.getElementById("category").addEventListener("change", (event) => update({ currentCategory: event.target.value }));
document.getElementById("sort").addEventListener("change", (event) => {
  const [key, direction] = event.target.value.split(":");
  update({ currentSort: { key, direction } });
});
document.querySelectorAll("[data-view]").forEach((button) => {
  button.addEventListener("click", () => update({ currentView: button.dataset.view }));
});
document.getElementById("prev").addEventListener("click", () => update({ currentPage: state.currentPage - 1 }));
document.getElementById("next").addEventListener("click", () => update({ currentPage: state.currentPage + 1 }));
render();
